content.query:
let teamFilter = '{Team}';
let subjectFilter = '{Subject}';
let providerFilter = '{Provider}';
let modelFilter = '{Model}';
let projectFilter = '{Project}';
let qualityFilter = '{TokenQuality}';
let eventFilter = '{EventId}';
AIRequestUsage_CL
| where TimeGenerated {TimeRange}
| where ResourceGroupId =~ '__RESOURCE_GROUP_ID__'
| where ModelResourceId =~ '__FOUNDRY_RESOURCE_ID__'
| extend Model = iff(isempty(ResponseModel), RequestModel, ResponseModel)
| where teamFilter == 'All' or TeamId == teamFilter
| where subjectFilter == 'All' or SubjectId == subjectFilter
| where providerFilter == 'All' or Provider == providerFilter
| where modelFilter == 'All' or Model == modelFilter
| where projectFilter == 'All' or ProjectId == projectFilter
| where qualityFilter == 'All' or TokenQuality == qualityFilter
| where eventFilter == 'All' or EventId == eventFilter
| project TimeGenerated, EventId, CorrelationId, TraceId, Provider, RequestModel, ResponseModel, DeploymentName, DeploymentType, ModelResourceId, ResourceGroupId, TeamId, SubjectId, ProjectId, AttributionMode, RequestOutcome, HttpStatusCode, LatencyMs, TokenQuality, InputTokens, CachedInputTokens, UncachedInputTokens, CacheWrite5mTokens, CacheWrite1hTokens, OutputTokens, ReasoningTokens, VisibleOutputTokens, TotalTokens, RateCardVersionId, EstimatedCost, PricingCurrency, EventHubPartition, EventHubSequenceNumber, ArchivePath
| order by TimeGenerated desc
| take 1000

let teamFilter = '{Team}';
let subjectFilter = '{Subject}';
let providerFilter = '{Provider}';
let statusFilter = '{AllocationStatus}';
let runFilter = '{RunId}';
AICostAllocation_CL
| where TimeGenerated {TimeRange}
| where SourceScope =~ '__RESOURCE_GROUP_ID__'
| where teamFilter == 'All' or TeamId == teamFilter
| where subjectFilter == 'All' or SubjectId == subjectFilter
| where providerFilter == 'All' or Provider == providerFilter
| where statusFilter == 'All' or AttributionStatus == statusFilter
| where runFilter == 'All' or RunId == runFilter
| project TimeGenerated, RunId, AllocationVersion, SourceType, SourceScope, ChargePeriodStart, ChargePeriodEnd, BillingPeriodStart, BillingPeriodEnd, Provider, PublisherName, MeterId, MeterName, ResourceId, BillingCurrency, SourceQuantity, SourceUnit, SourceBilledCost, SourceEffectiveCost, TeamId, SubjectId, AllocationBasis, AllocationWeight, AllocationRatio, AllocatedBilledCost, AllocatedEffectiveCost, UnallocatedBilledCost, UnallocatedEffectiveCost, AttributionStatus, IncludedInWorkloadTotal, RateCardVersionId, UsageSnapshotId, SourcePath, SourceETag
| order by TimeGenerated desc, ChargePeriodStart desc
| take 2000

let teamFilter = '{Team}';
let subjectFilter = '{Subject}';
let providerFilter = '{Provider}';
let modelFilter = '{Model}';
let projectFilter = '{Project}';
let usageExceptions = AIRequestUsage_CL
| where TimeGenerated {TimeRange}
| where ResourceGroupId =~ '__RESOURCE_GROUP_ID__' and ModelResourceId =~ '__FOUNDRY_RESOURCE_ID__'
| extend Model = iff(isempty(ResponseModel), RequestModel, ResponseModel)
| where teamFilter == 'All' or TeamId == teamFilter
| where subjectFilter == 'All' or SubjectId == subjectFilter
| where providerFilter == 'All' or Provider == providerFilter
| where modelFilter == 'All' or Model == modelFilter
| where projectFilter == 'All' or ProjectId == projectFilter
| extend Exception = case(isempty(RateCardVersionId) or RateCardVersionId == 'no-rate' or isnull(EstimatedCost), 'missing rate', isempty(TeamId) or TeamId == 'Unknown', 'unknown team', TokenQuality in ('missing', 'interrupted', 'unavailable'), strcat('token quality: ', TokenQuality), '')
| where isnotempty(Exception)
| project TimeGenerated, Source = 'Request', Exception, Provider, TeamId, SubjectId, EventOrRunId = EventId, TokenQuality, CostImpact = real(null), Evidence = ArchivePath;
let allocationExceptions = AICostAllocation_CL
| where TimeGenerated {TimeRange}
| where SourceScope =~ '__RESOURCE_GROUP_ID__'
| where AttributionStatus != 'allocated' or IncludedInWorkloadTotal == false
| where teamFilter == 'All' or TeamId == teamFilter
| where subjectFilter == 'All' or SubjectId == subjectFilter
| where providerFilter == 'All' or Provider == providerFilter
| project TimeGenerated, Source = 'Allocation', Exception = AttributionStatus, Provider, TeamId, SubjectId, EventOrRunId = RunId, TokenQuality = '', CostImpact = coalesce(UnallocatedEffectiveCost, UnallocatedBilledCost), Evidence = SourcePath;
union usageExceptions, allocationExceptions
| order by TimeGenerated desc
| take 1000

let eventFilter = '{EventId}';
let teamFilter = '{Team}';
let subjectFilter = '{Subject}';
AIRequestUsage_CL
| where TimeGenerated {TimeRange}
| where ResourceGroupId =~ '__RESOURCE_GROUP_ID__' and ModelResourceId =~ '__FOUNDRY_RESOURCE_ID__'
| where eventFilter == 'All' or EventId == eventFilter
| where teamFilter == 'All' or TeamId == teamFilter
| where subjectFilter == 'All' or SubjectId == subjectFilter
| project TimeGenerated, EventId, SchemaVersion, CorrelationId, TraceId, Provider, RequestModel, ResponseModel, TeamId, SubjectId, ProjectId, RequestOutcome, HttpStatusCode, TokenQuality, RawUsage, RateCardVersionId, EstimatedCost, PricingCurrency, EventHubPartition, EventHubSequenceNumber, ArchivePath
| order by TimeGenerated desc
| take 500
